CREATE TABLE IF NOT EXISTS codes ( id INTEGER PRIMARY KEY AUTOINCREMENT, code_hash TEXT NOT NULL UNIQUE, code_plain TEXT, plan TEXT NOT NULL, max_uses INTEGER, used INTEGER NOT NULL DEFAULT 0, expires_at INTEGER, days INTEGER, active INTEGER NOT NULL DEFAULT 1, note TEXT, created_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS keys ( id INTEGER PRIMARY KEY AUTOINCREMENT, key_hash TEXT NOT NULL UNIQUE, plan TEXT NOT NULL, expires_at INTEGER, active INTEGER NOT NULL DEFAULT 1, code_id INTEGER, dev_hash TEXT, switches INTEGER NOT NULL DEFAULT 0, switch_day TEXT, created_at INTEGER NOT NULL, replaced_at INTEGER );
CREATE INDEX IF NOT EXISTS keys_code_dev ON keys(code_id, dev_hash, active);
CREATE TABLE IF NOT EXISTS redemptions ( code_id INTEGER NOT NULL, dev_hash TEXT NOT NULL, at INTEGER NOT NULL, PRIMARY KEY (code_id, dev_hash) );
CREATE TABLE IF NOT EXISTS rate_limits (k TEXT PRIMARY KEY, n INTEGER NOT NULL, exp INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS admin_state ( id INTEGER PRIMARY KEY CHECK (id = 1), epoch TEXT, session_hash TEXT, transfer_hash TEXT, transfer_exp INTEGER );
CREATE TABLE IF NOT EXISTS admin_sessions (session_hash TEXT PRIMARY KEY, epoch TEXT NOT NULL, label TEXT, created_at INTEGER NOT NULL, last_seen INTEGER);
CREATE TABLE IF NOT EXISTS contributors (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, name_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'pending', pend_hash TEXT, ticket_hash TEXT, ticket_plain TEXT, session_hash TEXT, created_at INTEGER NOT NULL, decided_at INTEGER);
CREATE TABLE IF NOT EXISTS contrib_subs (id INTEGER PRIMARY KEY AUTOINCREMENT, contributor_id INTEGER NOT NULL, title TEXT NOT NULL, data TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', note TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS contrib_packs (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, data TEXT NOT NULL, published INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS community_docs (id INTEGER PRIMARY KEY AUTOINCREMENT, contributor_id INTEGER NOT NULL, author TEXT NOT NULL, title TEXT NOT NULL, html TEXT NOT NULL, snippet TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
